{"path":"website_museum_anthropic-claude-sonnet-5-5_01.html","content":"<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>ARTIFACT: Museum Night — 18 October 2026, The Old Gallery, Warsaw</title>
<meta name="description" content="ARTIFACT: Museum Night — a cinematic after-hours museum event with exhibitions, live performances, artist talks and hidden-room tours. 18 October 2026, Warsaw.">
<meta property="og:type" content="website">
<meta property="og:title" content="ARTIFACT: Museum Night">
<meta property="og:description" content="A cinematic after-hours museum event. 18 October 2026, 19:00–02:00, The Old Gallery, Warsaw.">
<meta property="og:image" content="https://source.unsplash.com/featured/1200x630?museum,night">
<meta name="theme-color" content="#070506">
<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='14' fill='%23070506'/%3E%3Cpath d='M32 10 50 52H42L38 42H26L22 52H14Z M29 34H35L32 26Z' fill='%23d6ad60' fill-rule='evenodd'/%3E%3C/svg%3E">
<style>
:root{
  --bg:#070506;--velvet:#1a0710;--burgundy:#3a0f1d;--navy:#07111f;
  --gold:#d6ad60;--soft:#f3d79b;--ivory:#f8efe2;--muted:#b9a999;
  --panel:rgba(255,244,220,.06);--border:rgba(214,173,96,.28);
  --serif:Georgia,"Times New Roman",serif;
  --sans:Inter,system-ui,"Segoe UI",sans-serif;
  --nav-h:72px;
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth;scroll-padding-top:calc(var(--nav-h) + 8px)}
body{background:var(--bg);color:var(--ivory);font-family:var(--sans);line-height:1.65;font-size:16px;overflow-x:hidden;-webkit-font-smoothing:antialiased}
body.locked{overflow:hidden}
body::before{content:"";position:fixed;inset:0;z-index:999;pointer-events:none;opacity:.07;mix-blend-mode:overlay;
  background-image:repeating-radial-gradient(circle at 17% 32%,#fff 0 .5px,transparent .5px 3px),repeating-radial-gradient(circle at 83% 68%,#fff 0 .5px,transparent .5px 4px);background-size:5px 5px,7px 7px}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
button{font:inherit;color:inherit;cursor:pointer}
h1,h2,h3,h4{font-family:var(--serif);font-weight:400;line-height:1.1;letter-spacing:-.01em}
:focus-visible{outline:2px solid var(--soft);outline-offset:3px;border-radius:4px}
.skip{position:absolute;left:-999px;top:8px;background:var(--gold);color:#000;padding:8px 14px;z-index:2000;border-radius:6px}
.skip:focus{left:8px}
.wrap{width:min(1200px,92%);margin-inline:auto}
section{position:relative;padding:clamp(72px,10vw,130px) 0}
.eyebrow{font-size:.75rem;letter-spacing:.32em;text-transform:uppercase;color:var(--gold);display:flex;align-items:center;gap:14px;margin-bottom:18px}
.eyebrow::before{content:"";width:40px;height:1px;background:var(--gold)}
.h2{font-size:clamp(2.2rem,5vw,4rem);margin-bottom:20px}
.h2 em{color:var(--soft);font-style:italic}
.lead{color:var(--muted);max-width:60ch;font-size:1.05rem}
.divider{height:1px;border:0;background:linear-gradient(90deg,transparent,var(--gold),transparent);opacity:.5}
.glass{background:var(--panel);border:1px solid var(--border);border-radius:18px;backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px)}

/* Buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;padding:14px 28px;border-radius:999px;border:1px solid var(--gold);background:transparent;color:var(--soft);font-weight:600;font-size:.88rem;letter-spacing:.08em;text-transform:uppercase;transition:transform .25s,background .25s,color .25s,box-shadow .25s}
.btn:hover{background:rgba(214,173,96,.14);transform:translateY(-2px);box-shadow:0 8px 30px rgba(214,173,96,.18)}
.btn.primary{background:linear-gradient(135deg,var(--soft),var(--gold));color:#1a0710;border-color:transparent}
.btn.primary:hover{box-shadow:0 10px 36px rgba(214,173,96,.45);background:linear-gradient(135deg,#fff0cc,var(--gold))}
.btn.sm{padding:10px 20px;font-size:.78rem}
.btn:disabled{opacity:.55;cursor:not-allowed;transform:none}

/* Navbar */
.nav{position:sticky;top:0;z-index:500;height:var(--nav-h);display:flex;align-items:center;transition:background .3s,border-color .3s;border-bottom:1px solid transparent}
.nav.scrolled{background:rgba(7,5,6,.82);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);border-color:var(--border)}
.nav .wrap{display:flex;align-items:center;justify-content:space-between;gap:20px}
.logo{font-family:var(--serif);letter-spacing:.42em;font-size:1.15rem;color:var(--soft)}
.logo span{color:var(--gold)}
.nav ul{display:flex;gap:34px;list-style:none}
.nav ul a{font-size:.82rem;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);padding:6px 0;position:relative;transition:color .25s}
.nav ul a::after{content:"";position:absolute;left:0;right:100%;bottom:0;height:1px;background:var(--gold);transition:right .3s}
.nav ul a:hover,.nav ul a.active{color:var(--soft)}
.nav ul a:hover::after,.nav ul a.active::after{right:0}
.nav-right{display:flex;align-items:center;gap:14px}
.burger{display:none;width:44px;height:44px;border-radius:50%;border:1px solid var(--border);background:var(--panel);position:relative}
.burger span,.burger span::before,.burger span::after{position:absolute;left:12px;width:18px;height:1.5px;background:var(--soft);content:"";transition:.3s}
.burger span{top:21px}.burger span::before{left:0;top:-6px}.burger span::after{left:0;top:6px}
.burger[aria-expanded=true] span{background:transparent}
.burger[aria-expanded=true] span::before{top:0;transform:rotate(45deg)}
.burger[aria-expanded=true] span::after{top:0;transform:rotate(-45deg)}

/* Hero */
.hero{min-height:calc(100vh - var(--nav-h));margin-top:calc(var(--nav-h) * -1);padding:calc(var(--nav-h) + 60px) 0 70px;display:flex;align-items:flex-end;overflow:hidden;isolation:isolate}
.hero-bg{position:absolute;inset:0;z-index:-3;background:radial-gradient(ellipse at 70% 30%,var(--burgundy),var(--velvet) 45%,var(--navy))}
.hero-bg img{width:100%;height:100%;object-fit:cover;filter:saturate(.8) contrast(1.05);transform:scale(1.06);animation:drift 28s ease-in-out infinite alternate}
@keyframes drift{to{transform:scale(1.15) translate(-1.5%,1%)}}
.hero::before{content:"";position:absolute;inset:0;z-index:-2;background:linear-gradient(180deg,rgba(7,5,6,.75) 0%,rgba(7,5,6,.45) 35%,rgba(7,5,6,.92) 88%,var(--bg) 100%),linear-gradient(90deg,rgba(26,7,16,.85),transparent 70%)}
.hero::after{content:"";position:absolute;inset:-10% 0 auto 0;height:120%;z-index:-1;pointer-events:none;background:radial-gradient(ellipse 28% 70% at 72% 0%,rgba(243,215,155,.30),transparent 70%),radial-gradient(ellipse 18% 55% at 25% 0%,rgba(214,173,96,.16),transparent 70%);animation:flicker 7s ease-in-out infinite}
@keyframes flicker{0%,100%{opacity:1}50%{opacity:.7}}
.hero-inner{display:grid;grid-template-columns:1.5fr 1fr;gap:50px;align-items:end;width:min(1200px,92%);margin-inline:auto}
.event-name{font-size:.85rem;letter-spacing:.4em;text-transform:uppercase;color:var(--gold);margin-bottom:22px}
.hero h1{font-size:clamp(3rem,8.5vw,7.4rem);line-height:.98;margin-bottom:28px}
.hero h1 em{display:block;font-style:italic;color:var(--soft)}
.hero p.sub{color:#dccfbd;max-width:52ch;font-size:1.1rem;margin-bottom:34px}
.cta-row{display:flex;flex-wrap:wrap;gap:14px}
.meta{display:grid;gap:12px}
.badge{display:flex;align-items:center;gap:14px;padding:16px 20px;border-radius:14px;background:rgba(7,5,6,.55);border:1px solid var(--border);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px)}
.badge svg{flex:none;width:22px;height:22px;stroke:var(--gold);fill:none;stroke-width:1.5}
.badge small{display:block;font-size:.68rem;letter-spacing:.22em;text-transform:uppercase;color:var(--muted)}
.badge b{font-family:var(--serif);font-weight:400;font-size:1.15rem;color:var(--ivory)}
.scroll-hint{position:absolute;bottom:18px;left:50%;width:1px;height:40px;background:linear-gradient(var(--gold),transparent);opacity:.7}

/* Concept */
.concept{background:radial-gradient(ellipse at 0% 0%,var(--velvet),transparent 60%)}
.concept-grid{display:grid;grid-template-columns:1fr 1.1fr;gap:60px;align-items:start;margin-bottom:60px}
.concept-grid p.body{color:var(--muted);font-size:1.12rem}
.concept-grid p.body::first-letter{font-family:var(--serif);float:left;font-size:4.4rem;line-height:.85;padding:6px 12px 0 0;color:var(--gold)}
.features{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}
.feature{padding:34px 30px;transition:transform .35s,border-color .35s,background .35s}
.feature:hover{transform:translateY(-6px);border-color:var(--gold);background:rgba(255,244,220,.09)}
.feature .num{font-family:var(--serif);font-size:.95rem;color:var(--gold);letter-spacing:.2em}
.feature h3{font-size:1.6rem;margin:14px 0 10px}
.feature p{color:var(--muted);font-size:.96rem}
.feature:nth-child(2){margin-top:34px}

/* Timeline */
.program{background:linear-gradient(180deg,var(--bg),var(--navy) 50%,var(--bg))}
.timeline{position:relative;margin-top:60px;padding-left:0}
.timeline::before{content:"";position:absolute;left:150px;top:0;bottom:0;width:1px;background:linear-gradient(transparent,var(--gold) 6%,var(--gold) 94%,transparent);opacity:.6}
.t-item{display:grid;grid-template-columns:150px 1fr;position:relative;padding-bottom:30px}
.t-time{font-family:var(--serif);font-size:2rem;color:var(--soft);padding-right:40px;text-align:right;line-height:1.2}
.t-item::after{content:"";position:absolute;left:145px;top:14px;width:11px;height:11px;border-radius:50%;background:var(--bg);border:1px solid var(--gold);box-shadow:0 0 0 4px rgba(214,173,96,.12);transition:.3s}
.t-item:hover::after{background:var(--gold);box-shadow:0 0 18px var(--gold)}
.t-card{margin-left:40px;padding:22px 28px;transition:transform .3s,border-color .3s}
.t-item:hover .t-card{transform:translateX(6px);border-color:var(--gold)}
.t-card h3{font-size:1.5rem;margin-bottom:6px}
.t-card p{color:var(--muted);font-size:.95rem;margin-bottom:12px}
.tag{display:inline-block;font-size:.68rem;letter-spacing:.18em;text-transform:uppercase;color:var(--gold);border:1px solid var(--border);border-radius:999px;padding:4px 12px}

/* Artists */
.artists-head{display:flex;justify-content:space-between;align-items:end;gap:30px;flex-wrap:wrap;margin-bottom:54px}
.artist-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:22px}
.artist{display:flex;flex-direction:column;overflow:hidden;transition:transform .4s,border-color .4s,box-shadow .4s}
.artist:nth-child(4n+2),.artist:nth-child(4n+4){margin-top:40px}
.artist:hover{transform:translateY(-8px);border-color:var(--gold);box-shadow:0 24px 60px rgba(0,0,0,.6),0 0 40px rgba(214,173,96,.08)}
.img-box{position:relative;overflow:hidden;background:linear-gradient(135deg,var(--burgundy),var(--navy));aspect-ratio:4/3.3}
.artist:nth-child(odd) .img-box{aspect-ratio:4/4.6}
.img-box img{width:100%;height:100%;object-fit:cover;filter:grayscale(.35) contrast(1.05);transition:transform .8s,filter .5s}
.artist:hover .img-box img{transform:scale(1.08);filter:grayscale(0) contrast(1.05)}
.img-box::after{content:"";position:absolute;inset:0;background:linear-gradient(transparent 55%,rgba(7,5,6,.75))}
.img-box .mono{position:absolute;inset:0;display:grid;place-items:center;font-family:var(--serif);font-size:3rem;color:rgba(214,173,96,.35);z-index:0}
.img-box img{position:relative;z-index:1}
.artist-body{padding:20px 22px 24px;display:flex;flex-direction:column;gap:6px;flex:1}
.artist-body h3{font-size:1.35rem}
.role{font-size:.72rem;letter-spacing:.18em;text-transform:uppercase;color:var(--gold)}
.artist-body p{color:var(--muted);font-size:.92rem;flex:1;margin-bottom:10px}

/* Venue */
.venue{background:radial-gradient(ellipse at 100% 50%,var(--burgundy),transparent 55%)}
.venue-grid{display:grid;grid-template-columns:1fr 1.15fr;gap:50px;align-items:center}
.venue-list{display:grid;gap:14px;margin-top:28px}
.venue-item{padding:18px 22px}
.venue-item h4{font-family:var(--sans);font-size:.74rem;letter-spacing:.22em;text-transform:uppercase;color:var(--gold);margin-bottom:4px;font-weight:600}
.venue-item p{color:var(--muted);font-size:.95rem}
.venue-item p strong{color:var(--ivory);font-weight:500}
.map{padding:14px;overflow:hidden}
.map svg{width:100%;height:auto;display:block;border-radius:12px}
.map-legend{display:flex;flex-wrap:wrap;gap:16px;padding:14px 8px 4px;font-size:.78rem;color:var(--muted)}
.map-legend i{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:7px;vertical-align:middle}
.route{stroke-dasharray:6 7;animation:dash 1.6s linear infinite}
@keyframes dash{to{stroke-dashoffset:-26}}
.pulse{transform-box:fill-box;transform-origin:center;animation:pulse 2.2s ease-out infinite}
@keyframes pulse{0%{transform:scale(.6);opacity:.8}100%{transform:scale(2.4);opacity:0}}

/* Tickets */
.tickets{background:linear-gradient(180deg,var(--bg),var(--velvet) 60%,var(--bg))}
.center{text-align:center}.center .eyebrow{justify-content:center}.center .eyebrow::after{content:"";width:40px;height:1px;background:var(--gold)}.center .lead{margin-inline:auto}
.tier-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:26px;margin-top:64px;align-items:stretch}
.tier{position:relative;padding:40px 34px;display:flex;flex-direction:column;transition:transform .4s,border-color .4s,box-shadow .4s,background .4s}
.tier::before{content:"";position:absolute;inset:0;border-radius:inherit;background:radial-gradient(ellipse at 50% 0%,rgba(243,215,155,.14),transparent 65%);opacity:0;transition:opacity .4s;pointer-events:none}
.tier:hover{transform:translateY(-10px);border-color:var(--gold);box-shadow:0 30px 80px rgba(0,0,0,.6),0 0 50px rgba(214,173,96,.14)}
.tier:hover::before{opacity:1}
.tier.featured{border-color:var(--gold);background:linear-gradient(180deg,rgba(214,173,96,.12),rgba(58,15,29,.45));transform:translateY(-16px)}
.tier.featured:hover{transform:translateY(-24px)}
.ribbon{position:absolute;top:-14px;left:50%;transform:translateX(-50%);background:linear-gradient(135deg,var(--soft),var(--gold));color:#1a0710;font-size:.68rem;font-weight:700;letter-spacing:.2em;text-transform:uppercase;padding:6px 16px;border-radius:999px;white-space:nowrap}
.tier h3{font-size:1.8rem}
.price{font-family:var(--serif);font-size:3.6rem;color:var(--soft);margin:14px 0 4px;line-height:1}
.price small{font-size:.9rem;color:var(--muted);font-family:var(--sans);margin-left:6px}
.tier ul{list-style:none;margin:26px 0 34px;padding-top:26px;border-top:1px solid var(--border);display:grid;gap:13px;flex:1}
.tier li{display:flex;gap:12px;color:#d9ccba;font-size:.96rem}
.tier li::before{content:"";flex:none;width:7px;height:7px;margin-top:9px;transform:rotate(45deg);background:var(--gold)}
.tier .btn{width:100%}
.tier-note{text-align:center;margin-top:40px;color:var(--muted);font-size:.85rem}

/* FAQ */
.faq-wrap{max-width:860px}
.faq-list{margin-top:46px;border-top:1px solid var(--border)}
.faq-item{border-bottom:1px solid var(--border)}
.faq-q{width:100%;display:flex;justify-content:space-between;align-items:center;gap:20px;background:none;border:0;padding:26px 4px;text-align:left;font-family:var(--serif);font-size:1.3rem;color:var(--ivory);transition:color .25s}
.faq-q:hover{color:var(--soft)}
.faq-q .pm{flex:none;width:32px;height:32px;border:1px solid var(--border);border-radius:50%;position:relative;transition:.3s}
.faq-q .pm::before,.faq-q .pm::after{content:"";position:absolute;left:50%;top:50%;width:12px;height:1.5px;background:var(--gold);transform:translate(-50%,-50%);transition:.3s}
.faq-q .pm::after{transform:translate(-50%,-50%) rotate(90deg)}
.faq-q[aria-expanded=true] .pm{background:rgba(214,173,96,.15);transform:rotate(180deg)}
.faq-q[aria-expanded=true] .pm::after{transform:translate(-50%,-50%) rotate(0)}
.faq-a{display:grid;grid-template-rows:0fr;transition:grid-template-rows .4s ease}
.faq-a.open{grid-template-rows:1fr}
.faq-a>div{overflow:hidden}
.faq-a p{color:var(--muted);padding:0 50px 26px 4px}

/* Newsletter */
.news{padding:clamp(60px,8vw,100px) 0}
.news-box{padding:clamp(34px,6vw,70px);text-align:center;background:linear-gradient(135deg,rgba(58,15,29,.7),rgba(7,17,31,.7));position:relative;overflow:hidden}
.news-box::before{content:"";position:absolute;inset:-40% 20% auto;height:80%;background:radial-gradient(ellipse,rgba(243,215,155,.18),transparent 70%);pointer-events:none}
.news-box>*{position:relative}
.news-form{display:flex;gap:12px;max-width:560px;margin:30px auto 0;flex-wrap:wrap}
.news-form .field{flex:1 1 260px;text-align:left}

/* Forms */
.field label{display:block;font-size:.72rem;letter-spacing:.18em;text-transform:uppercase;color:var(--gold);margin-bottom:8px}
.input{width:100%;background:rgba(7,5,6,.6);border:1px solid var(--border);border-radius:12px;color:var(--ivory);padding:14px 16px;font:inherit;transition:border-color .25s,box-shadow .25s}
.input::placeholder{color:#7d7064}
.input:hover{border-color:rgba(214,173,96,.55)}
.input:focus{outline:none;border-color:var(--soft);box-shadow:0 0 0 3px rgba(243,215,155,.18)}
.input[aria-invalid=true]{border-color:#e0788a}
.err{color:#f0a0ae;font-size:.8rem;min-height:1.3em;margin-top:6px}

/* Footer */
footer{border-top:1px solid var(--border);padding:70px 0 34px;background:linear-gradient(180deg,var(--bg),var(--velvet))}
.foot-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:40px;margin-bottom:50px}
.foot-grid h4{font-family:var(--sans);font-size:.72rem;letter-spacing:.22em;text-transform:uppercase;color:var(--gold);margin-bottom:16px;font-weight:600}
.foot-grid p,.foot-grid li{color:var(--muted);font-size:.92rem}
.foot-grid ul{list-style:none;display:grid;gap:8px}
.foot-grid a{transition:color .25s}.foot-grid a:hover{color:var(--soft)}
.foot-bottom{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;padding-top:26px;border-top:1px solid var(--border);font-size:.82rem;color:var(--muted)}
.foot-bottom em{color:var(--soft)}

/* Modal */
.overlay{position:fixed;inset:0;z-index:1000;display:none;align-items:center;justify-content:center;padding:20px;background:rgba(4,2,3,.82);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);opacity:0;transition:opacity .3s}
.overlay.show{display:flex}
.overlay.vis{opacity:1}
.modal{position:relative;width:min(960px,100%);max-height:92vh;overflow:auto;background:linear-gradient(160deg,#1c0a13,#0a0d18);border:1px solid var(--border);border-radius:22px;box-shadow:0 40px 120px #000;transform:translateY(24px) scale(.98);transition:transform .35s}
.overlay.vis .modal{transform:none}
.modal.narrow{width:min(560px,100%);padding:38px 34px}
.m-close{position:absolute;top:14px;right:14px;z-index:5;width:42px;height:42px;border-radius:50%;border:1px solid var(--border);background:rgba(7,5,6,.7);font-size:1.3rem;line-height:1;transition:.25s}
.m-close:hover{background:var(--gold);color:#1a0710}
.artist-modal{display:grid;grid-template-columns:1fr 1.1fr}
.artist-modal .img-box{aspect-ratio:auto;min-height:340px;height:100%}
.am-body{padding:44px 38px}
.am-body h2{font-size:2.4rem;margin:8px 0 14px}
.am-body p{color:var(--muted);margin-bottom:18px}
.session{display:inline-flex;gap:10px;align-items:center;padding:10px 16px;border:1px solid var(--border);border-radius:12px;background:var(--panel);font-size:.9rem;color:var(--soft)}
.modal h2#tm-title{font-size:2rem;margin:6px 0 6px}
.form-grid{display:grid;gap:16px;margin-top:22px}
.tier-pick{display:flex;gap:8px;flex-wrap:wrap}
.tier-pick label{flex:1;margin:0;cursor:pointer}
.tier-pick input{position:absolute;opacity:0;pointer-events:none}
.tier-pick span{display:block;text-align:center;padding:10px 8px;border:1px solid var(--border);border-radius:12px;font-size:.78rem;letter-spacing:.06em;text-transform:none;color:var(--muted);transition:.25s}
.tier-pick label:hover span{border-color:var(--gold)}
.tier-pick input:checked+span{background:rgba(214,173,96,.16);border-color:var(--gold);color:var(--soft)}
.tier-pick input:focus-visible+span{outline:2px solid var(--soft);outline-offset:2px}
.qty{display:flex;align-items:center;gap:0;width:max-content;border:1px solid var(--border);border-radius:12px;overflow:hidden}
.qty button{width:44px;height:44px;background:var(--panel);border:0;font-size:1.2rem;transition:.2s}
.qty button:hover{background:rgba(214,173,96,.2)}
.qty output{min-width:52px;text-align:center;font-family:var(--serif);font-size:1.2rem}
.total{display:flex;justify-content:space-between;align-items:baseline;padding:18px 0;border-top:1px solid var(--border);border-bottom:1px solid var(--border)}
.total b{font-family:var(--serif);font-weight:400;font-size:2.2rem;color:var(--soft)}
.check{display:flex;gap:12px;align-items:flex-start;font-size:.9rem;color:var(--muted);cursor:pointer}
.check input{width:20px;height:20px;accent-color:var(--gold);margin-top:2px;flex:none}
.success{text-align:center;padding:20px 0}
.success .seal{width:76px;height:76px;margin:0 auto 20px;border-radius:50%;border:1px solid var(--gold);display:grid;place-items:center;box-shadow:0 0 40px rgba(214,173,96,.3)}
.success .seal svg{width:34px;height:34px;stroke:var(--soft);fill:none;stroke-width:2}
.success h2{font-size:2rem;margin-bottom:10px}
.success p{color:var(--muted);margin-bottom:22px}
[hidden]{display:none!important}

/* Toasts */
.toasts{position:fixed;right:20px;bottom:20px;z-index:1500;display:grid;gap:10px;max-width:calc(100% - 40px)}
.toast{display:flex;gap:12px;align-items:center;padding:14px 20px;background:rgba(20,8,14,.95);border:1px solid var(--gold);border-radius:14px;box-shadow:0 14px 50px rgba(0,0,0,.7);color:var(--ivory);font-size:.92rem;animation:tin .4s both}
.toast.err-t{border-color:#e0788a}
.toast::before{content:"";flex:none;width:8px;height:8px;transform:rotate(45deg);background:var(--gold)}
.toast.err-t::before{background:#e0788a}
.toast.out{animation:tout .35s both}
@keyframes tin{from{opacity:0;transform:translateY(16px)}}
@keyframes tout{to{opacity:0;transform:translateX(30px)}}

/* Reveal */
.reveal{opacity:0;transform:translateY(32px);transition:opacity .9s cubic-bezier(.2,.7,.2,1),transform .9s cubic-bezier(.2,.7,.2,1);transition-delay:var(--d,0s)}
.reveal.in{opacity:1;transform:none}
.no-js .reveal{opacity:1;transform:none}

/* Responsive */
@media(max-width:1040px){
  .artist-grid{grid-template-columns:repeat(2,1fr)}
  .artist:nth-child(n){margin-top:0}.artist:nth-child(even){margin-top:34px}
  .hero-inner{grid-template-columns:1fr}
  .meta{grid-template-columns:repeat(3,1fr)}
}
@media(max-width:900px){
  .nav ul{position:fixed;top:var(--nav-h);left:0;right:0;flex-direction:column;gap:0;background:rgba(7,5,6,.97);backdrop-filter:blur(18px);border-bottom:1px solid var(--border);padding:10px 6%;transform:translateY(-12px);opacity:0;visibility:hidden;transition:.3s}
  .nav ul.open{transform:none;opacity:1;visibility:visible}
  .nav ul a{display:block;padding:16px 0;border-bottom:1px solid rgba(214,173,96,.12);font-size:.95rem}
  .burger{display:block}
  .nav-right .btn{display:none}
  .concept-grid,.venue-grid{grid-template-columns:1fr;gap:36px}
  .features{grid-template-columns:1fr}.feature:nth-child(2){margin-top:0}
  .tier-grid{grid-template-columns:1fr;max-width:460px;margin-inline:auto}
  .tier.featured,.tier.featured:hover{transform:none}
  .tier.featured{margin-block:14px}
  .artist-modal{grid-template-columns:1fr}.artist-modal .img-box{min-height:220px;max-height:280px}
  .foot-grid{grid-template-columns:1fr 1fr}.foot-grid>div:first-child{grid-column:1/-1}
}
@media(max-width:640px){
  .meta{grid-template-columns:1fr}
  .artist-grid{grid-template-columns:1fr}.artist:nth-child(n){margin-top:0}
  .artist .img-box,.artist:nth-child(odd) .img-box{aspect-ratio:4/3}
  .timeline::before{left:7px}
  .t-item{grid-template-columns:1fr;padding-left:32px}
  .t-item::after{left:2px;top:10px}
  .t-time{text-align:left;padding:0;font-size:1.5rem;margin-bottom:8px}
  .t-card{margin-left:0;padding:18px 20px}
  .faq-q{font-size:1.1rem}.faq-a p{padding-right:10px}
  .modal.narrow{padding:32px 20px 24px}.am-body{padding:28px 22px}
  .cta-row .btn{flex:1 1 100%}
  .toasts{left:20px;right:20px}
  .foot-grid{grid-template-columns:1fr}
}
@media(prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*::before,*::after{animation:none!important;transition-duration:.01ms!important}
  .reveal{opacity:1;transform:none}
}
