/* Image fallback (remote images may fail) */
function bindFallback(root){
 $$('img[data-fallback]',root).forEach(function(img){
  function fail(){img.style.display='none'}
  img.addEventListener('error',fail);
  if(img.complete&&img.naturalWidth===0&&img.src)fail();
 });
}
bindFallback(document);

/* ---------- Toast ---------- */
function toast(msg,isErr){
 var t=document.createElement('div');t.className='toast'+(isErr?' err-t':'');t.textContent=msg;
 $('#toasts').appendChild(t);
 setTimeout(function(){t.classList.add('out');setTimeout(function(){t.remove()},400)},4200);
}

