function setActive(){
 var y=window.scrollY+nav.offsetHeight+Math.min(200,window.innerHeight*.3),cur=-1;
 secs.forEach(function(s,i){if(s&&s.offsetTop<=y)cur=i});
 // newsletter/footer zone belongs to FAQ
