/* ---------- Modals ---------- */
var active=null,lastFocus=null;
var FOCUSABLE='a[href],button:not([disabled]),input:not([disabled]),select,textarea,[tabindex]:not([tabindex="-1"])';
function openModal(ov){
 lastFocus=document.activeElement;active=ov;
 ov.classList.add('show');ov.setAttribute('aria-hidden','false');document.body.classList.add('locked');
 requestAnimationFrame(function(){ov.classList.add('vis');var m=$('.modal',ov);var f=$('input:not([type=radio]),[data-close]',m);(f&&f.offsetParent?f:m).focus()});
}
function closeModal(){
 if(!active)return;var ov=active;active=null;
 ov.classList.remove('vis');ov.setAttribute('aria-hidden','true');
 setTimeout(function(){ov.classList.remove('show');document.body.classList.remove('locked')},250);
 if(lastFocus&&lastFocus.focus)lastFocus.focus();
}
$$('.overlay').forEach(function(ov){
 ov.addEventListener('mousedown',function(e){if(e.target===ov)closeModal()});
 $$('[data-close]',ov).forEach(function(b){b.addEventListener('click',closeModal)});
});
document.addEventListener('keydown',function(e){
 if(!active)return;
 if(e.key==='Escape'){e.preventDefault();closeModal();return}
 if(e.key==='Tab'){
  var f=$$(FOCUSABLE,active).filter(function(x){return x.offsetParent!==null&&x.type!=='radio'||x.type==='radio'&&x.checked&&x.offsetParent!==null||x.closest('.tier-pick')&&x.checked});
  if(!f.length)return;var first=f[0],last=f[f.length-1];
  if(e.shiftKey&&(document.activeElement===first||document.activeElement===active.firstElementChild)){e.preventDefault();last.focus()}
  else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}
 }
});

