/* Ticket modal */
var state={tier:'curator',qty:1};
var tForm=$('#ticket-form');
function updateTotal(){
 var t=tiers[state.tier];$('#q-val').textContent=state.qty;
 $('#t-total').textContent='€'+(t.price*state.qty);
 $$('input[name=tier]',tForm).forEach(function(r){r.checked=r.value===state.tier});
}
function clearErr(){$$('.err',tForm).forEach(function(x){x.textContent=''});$$('.input',tForm).forEach(function(x){x.removeAttribute('aria-invalid')})}
function openTicket(k){
 state.tier=k;state.qty=1;tForm.reset();clearErr();updateTotal();
 tForm.hidden=false;$('#ticket-success').hidden=true;
 openModal($('#ticket-overlay'));
}
$$('[data-tier]').forEach(function(b){b.addEventListener('click',function(){openTicket(b.getAttribute('data-tier'))})});
$$('input[name=tier]',tForm).forEach(function(r){r.addEventListener('change',function(){state.tier=r.value;updateTotal()})});
$('#q-minus').addEventListener('click',function(){if(state.qty>1){state.qty--;updateTotal()}});
$('#q-plus').addEventListener('click',function(){if(state.qty<10){state.qty++;updateTotal()}else toast('Maximum 10 tickets per reservation.',true)});
var emailRe=/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
function setErr(input,errEl,msg){errEl.textContent=msg;if(input){if(msg)input.setAttribute('aria-invalid','true');else input.removeAttribute('aria-invalid')}return !msg}
tForm.addEventListener('submit',function(e){
 e.preventDefault();
 var n=$('#t-name'),m=$('#t-email'),c=$('#t-terms');
 var nv=n.value.trim(),mv=m.value.trim();
 var ok1=setErr(n,$('#t-name-e'),nv.length<2?'Please enter the attendee’s full name.':'');
 var ok2=setErr(m,$('#t-email-e'),!mv?'Email is required.':(!emailRe.test(mv)?'Please enter a valid email address.':''));
 var ok3=setErr(null,$('#t-terms-e'),c.checked?'':'Please accept the terms to continue.');
 if(!(ok1&&ok2&&ok3)){toast('Please fix the highlighted fields.',true);var f=!ok1?n:!ok2?m:c;f.focus();return}
 var t=tiers[state.tier],total=t.price*state.qty;
 $('#ok-text').textContent=state.qty+' × '+t.name+' reserved for '+nv+' — total €'+total+'. A demo confirmation would be sent to '+mv+'. No payment was taken.';
 tForm.hidden=true;$('#ticket-success').hidden=false;$('#ok-title').focus();
 toast('Reservation confirmed — see you after dark!');
});

